R=Path(__file__).resolve().parent;S=Path('/workspace/scratch/TCGA_LIHC_candidate30_survival');src=Path('/workspace/scratch/PGAM5_myeloid_reference_v2/GSE151530_harmonized_counts_QC.h5ad');a=ad.read_h5ad(src);assert a.obs.dataset.astype(str).unique().tolist()==['GSE151530'];manifest=json.loads((R/'locked_reference_manifest.json').read_text());prep=json.loads((R/'preparation_summary.json').read_text());result=json.loads((R/'reference_result.json').read_text());de=pd.read_csv(R/'GSE151530_macrophage_DE_full.csv');sig=pd.read_csv(R/'GSE151530_target_candidate_signature.csv');ev=pd.read_csv(R/'selected_gene_evidence.csv');ref=pd.read_csv(R/'GSE151530_ONLY_EXPLORATORY_REFERENCE_CP10k.tsv',sep='\t',index_col=0);scale=pd.read_csv(R/'reference_row_scales.csv');support=pd.read_csv(R/'reference_group_support.csv');rng=np.random.default_rng(20261009)
assert de.gene.is_unique and ref.index.tolist()==manifest['genes'] and ref.columns.tolist()==manifest['reference_groups'];assert len(de)==a.n_vars;assert de.p_value.notna().all();q=multipletests(de.p_value.to_numpy(),method='fdr_bh')[1];assert np.allclose(q,de.FDR,rtol=1e-10,atol=1e-14);assert np.array_equal(de.strict_up_pass,(de.FDR<.05)&(de.scanpy_approx_log2FC>=1)&(de.target_detection_fraction>=.10));assert set(sig.gene)==set(manifest['target_panel']);assert sig.loc[sig.gene.ne('PGAM5'),'strict_up_pass'].all();assert sig.loc[sig.gene.ne('PGAM5'),'class_contrast_log2_plus0p05'].gt(0).all()
