for j,g in enumerate(samplegenes):
 x=xx[pos,j];y=xx[~pos,j];mwu=mannwhitneyu(x,y,alternative='two-sided',method='asymptotic',use_continuity=False);r=dindex.loc[g];independent_p=1. if np.ptp(xx[:,j])==0 else float(mwu.pvalue);assert np.isclose(independent_p,r.p_value,rtol=1e-8,atol=1e-10);ranks=rankdata(xx[:,j]);n1=len(x);n0=len(y);N=n1+n0;_,ties=np.unique(xx[:,j],return_counts=True);tc=1-np.sum(ties.astype(float)**3-ties)/(N**3-N);sd=np.sqrt(tc*n1*n0*(N+1)/12);U=ranks[pos].sum()-n1*(n1+1)/2;z=(U-n1*n0/2)/sd if sd>0 else 0;assert np.float32(z)==np.float32(r.scores);fc=np.log2((np.expm1(x.mean())+1e-9)/(np.expm1(y.mean())+1e-9));assert np.isclose(fc,r.scanpy_approx_log2FC,atol=1e-4);assert np.isclose((x>0).mean(),r.target_detection_fraction);genechecks.append({'gene':g,'independent_p':independent_p,'exported_p':float(r.p_value),'independent_score':float(z),'exported_score':float(r.scores),'independent_approx_log2FC':float(fc),'matched':True})
assert len(genechecks)==len(samplegenes) and len(genechecks)>=50
