for _,z in support.iterrows():
 mask=a.obs.fine_group.astype(str).isin(z.fine_groups_merged.split(';')).to_numpy();donor=a.obs.donor_id.astype(str).to_numpy();means=[]
 for d in sorted(set(donor[mask])):means.append(np.asarray(norm[mask&(donor==d)].mean(0)).ravel())
 estimated=np.mean(means,axis=0);err=float(abs(estimated-ref[z.reference_group].to_numpy()).max());assert err<1e-10;assert int(mask.sum())==z.cells;refchecks.append({'group':z.reference_group,'cells':int(mask.sum()),'donors':len(means),'max_mean_CP10k_error':err})
pd.DataFrame(refchecks).to_csv(R/'independent_reference_mean_checks.csv',index=False);expected=np.maximum(np.sqrt(np.mean(ref.to_numpy()**2,axis=1)),1e-6);assert np.allclose(expected,scale.row_scale,atol=1e-12);A=ref.to_numpy()/scale.row_scale.to_numpy()[:,None];exact=[]
for j in range(20):
 w=rng.dirichlet(np.ones(A.shape[1]));beta,res=nnls(A,A@w,maxiter=3000);err=float(abs(beta-w).max());assert err<1e-6;exact.append({'case':j,'max_coefficient_error':err,'residual':res})
pd.DataFrame(exact).to_csv(R/'exact_reference_recovery_checks.csv',index=False)
