 header=f.readline().rstrip('\r\n').split('\t')[1:];idx=[header.index(v)+1 for v in subset.RNA_sample]
 for line in f:
  cells=line.rstrip('\r\n').split('\t');v=np.array([float(cells[j]) for j in idx]);total+=v
