actual=pd.DataFrame(recovered,index=subset.patient).reindex(columns=counts.columns);assert np.array_equal(actual.to_numpy(),counts.loc[subset.patient].to_numpy());assert np.array_equal(total,subset.assigned_gene_counts);assert np.allclose(cp,counts.div(p.set_index('patient').assigned_gene_counts.reindex(counts.index),axis=0)*1e4,rtol=1e-12,atol=1e-10);assert np.allclose(w.sum(axis=1),1);assert np.allclose(p.exploratory_target_fraction,w.loc[p.patient,'TAM_PGAM5_detected']);assert np.allclose(p.exploratory_target_percent,p.exploratory_target_fraction*100);assert np.array_equal(p.group,np.where(p.exploratory_target_fraction>p.exploratory_target_fraction.median(),'High','Low'))
