missing=set(pd.read_csv(R/'missing_reference_genes.csv').gene);sig['available_in_TCGA']=~sig.gene.isin(missing);sig['selection_score']=sig.class_contrast_log2_plus0p05*np.minimum(1,sig.mean_CP10k);sig.sort_values('selection_score',ascending=False).to_csv(R/'GSE151530_target_signature_with_TCGA_coverage.csv',index=False)
